const u=/^[a-zA-Z0-9._+@-]{3,64}$/,s='用户名仅可包含字母、数字与 "."、"_"、"-"、"+"、"@"，长度 3-64 位';function g(r="请输入用户名"){return[{required:!0,message:r,trigger:"blur"},{min:3,max:64,message:"用户名长度为 3 到 64 个字符",trigger:"blur"},{pattern:u,message:s,trigger:"blur"}]}function o(r,n="请再次输入密码"){return{validator:(i,t,e)=>{if(!t){e(new Error(n));return}if(t!==r()){e(new Error("两次输入的密码不一致"));return}e()},trigger:"blur"}}export{o as c,g as u};
